import{_ as i,o as e,c as t,a2 as s}from"./chunks/framework.BqNd1sPY.js";const p=JSON.parse('{"title":"D17：搭建微型 Transformer","description":"","frontmatter":{},"headers":[],"relativePath":"02-第3周实战/D17-搭建微型Transformer.md","filePath":"02-第3周实战/D17-搭建微型Transformer.md"}'),r={name:"02-第3周实战/D17-搭建微型Transformer.md"};function o(n,a,d,l,c,k){return e(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="d17-搭建微型-transformer" tabindex="-1">D17：搭建微型 Transformer <a class="header-anchor" href="#d17-搭建微型-transformer" aria-label="Permalink to &quot;D17：搭建微型 Transformer&quot;">​</a></h1><h2 id="按数据流读代码" tabindex="-1">按数据流读代码 <a class="header-anchor" href="#按数据流读代码" aria-label="Permalink to &quot;按数据流读代码&quot;">​</a></h2><ol><li><code>tokenizer.py</code>：字符与 ID 互转。</li><li><code>data.py</code>：构造错开一位的输入与目标。</li><li><code>model.py</code>：<a href="/LLMTrain/05-速查表/术语速查#term-embedding" class="wiki-term" data-wiki-title="embedding" data-wiki-summary="把离散 ID 映射为连续向量的可训练表示。" data-wiki-misconception="embedding 是人工指定的固定语义坐标。">Embedding</a>、因果<a href="/LLMTrain/05-速查表/术语速查#term-attention" class="wiki-term" data-wiki-title="attention" data-wiki-summary="根据 Query 与 Key 的匹配权重，对 Value 做加权汇总。" data-wiki-misconception="注意力权重就是完整、可靠的人类可读解释。">注意力</a>、MLP、残差、Norm 和 LM Head。</li><li><code>train.py</code>：前向、反向、更新、验证和保存。</li></ol><p>先运行测试，再改代码：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">python.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m unittest discover </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s tests </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>关键测试 <code>test_future_tokens_do_not_change_prefix_logits</code> 构造两个拥有相同前缀、不同后缀的序列。如果<a href="/LLMTrain/05-速查表/术语速查#term-causal-mask" class="wiki-term" data-wiki-title="causal mask" data-wiki-summary="在自回归训练中阻止当前位置读取未来 token 的遮罩。" data-wiki-misconception="它会阻止模型读取当前位置之前的内容。">因果遮罩</a>正确，前缀位置的 <a href="/LLMTrain/05-速查表/术语速查#term-logits" class="wiki-term" data-wiki-title="logits" data-wiki-summary="softmax 之前的任意实数分数，用来比较各候选 token。" data-wiki-misconception="logits 已经是概率或正确率。">logits</a> 不应因未来 <a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> 改变。</p><h2 id="形状练习" tabindex="-1">形状练习 <a class="header-anchor" href="#形状练习" aria-label="Permalink to &quot;形状练习&quot;">​</a></h2><p>若 <code>batch=4, time=32, embedding=64, vocab=100</code>：</p><ul><li><a href="/LLMTrain/05-速查表/术语速查#term-token" class="wiki-term" data-wiki-title="token" data-wiki-summary="文本经过分词规则得到的离散单元，随后会映射成整数 ID。" data-wiki-misconception="token 必然等于一个字或一个完整单词。">token</a> ID：<code>(4, 32)</code></li><li>隐藏状态：<code>(4, 32, 64)</code></li><li><a href="/LLMTrain/05-速查表/术语速查#term-logits" class="wiki-term" data-wiki-title="logits" data-wiki-summary="softmax 之前的任意实数分数，用来比较各候选 token。" data-wiki-misconception="logits 已经是概率或正确率。">logits</a>：<code>(4, 32, 100)</code></li><li>targets：<code>(4, 32)</code></li><li>平均<a href="/LLMTrain/05-速查表/术语速查#term-cross-entropy" class="wiki-term" data-wiki-title="cross-entropy" data-wiki-summary="衡量目标分布与预测分布差异的常用损失；分类时等价于正确类别的负对数概率。" data-wiki-misconception="交叉熵就是准确率。">交叉熵</a>：一个标量</li></ul><h2 id="今日验收" tabindex="-1">今日验收 <a class="header-anchor" href="#今日验收" aria-label="Permalink to &quot;今日验收&quot;">​</a></h2><p>不用看代码，画出 <code>TinyLanguageModel.forward()</code> 的形状变化；再解释为什么 LM Head 最后一维必须等于<a href="/LLMTrain/05-速查表/术语速查#term-vocab" class="wiki-term" data-wiki-title="vocab" data-wiki-summary="tokenizer 可以表示的 token 集合；输出层通常也对这组 token 给出分数。" data-wiki-misconception="词表包含了模型掌握的全部知识。">词表</a>大小。</p>',11)])])}const h=i(r,[["render",o]]);export{p as __pageData,h as default};
